export const humanizeOrchestrationStage = (stageKey = ''): string => {
  const normalized = String(stageKey).trim();
  if (!normalized) {
    return 'Processing';
  }
  if (STAGE_MSME_LABELS[normalized]) {
    return STAGE_MSME_LABELS[normalized];
  }
  return normalized.replace(/_/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase());
};

export const buildStageOutcomeBullets = (
  stages: Array<{ stage: string; status: string }> = []
): string[] => {
  const bullets: string[] = [];
  stages.forEach((entry) => {
    if (entry.status === 'completed') {
      bullets.push(humanizeOrchestrationStage(entry.stage));
    }
  });
  if (stages.some((entry) => entry.status === 'failed')) {
    bullets.push('Some checks need your review — see the action list below.');
  }
  return bullets.slice(-5);
};

